package com.flow.adhd.domain

import java.time.ZoneId
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.long
import org.junit.Assert.assertEquals
import org.junit.Test
import org.junit.runner.RunWith
import org.junit.runners.Parameterized

/** Import and restore expectations are generated by the existing TypeScript persistence code. */
@RunWith(Parameterized::class)
class NativeImportParityTest(private val name: String, private val fixture: JsonObject) {
    @Test fun matchesTypeScriptPersistedState() {
        val command = FlowCommandCodec.decode(fixture["command"] as JsonObject)
        val result = FlowEngine(taskXp).apply(
            FlowSnapshot.parse((fixture["initialState"] as JsonObject).toString()),
            command,
            ZoneId.of(fixture.text("zone")),
            fixture.number("now"),
        )
        val applied = result as? FlowCommandResult.Applied
            ?: throw AssertionError("$name rejected: $result")
        val expected = fixture["expectedState"] as JsonObject
        val actual = JsonObject(expected.keys.mapNotNull { key -> applied.snapshot.data[key]?.let { key to it } }.toMap())
        assertEquals(name, expected, actual)
    }

    companion object {
        private lateinit var taskXp: Map<String, Double>
        @JvmStatic @Parameterized.Parameters(name = "{0}")
        fun cases(): List<Array<Any>> {
            val root = NativeImportParityTest::class.java.getResourceAsStream("/native-import-parity.json")!!
                .bufferedReader(Charsets.UTF_8).use { Json.parseToJsonElement(it.readText()) as JsonObject }
            taskXp = (root["taskXp"] as JsonObject).mapValues { (_, value) -> (value as JsonPrimitive).content.toDouble() }
            return (root["cases"] as JsonArray).mapIndexed { index, raw ->
                val fixture = raw as JsonObject
                arrayOf(fixture.text("name") ?: "import-$index", fixture)
            }
        }

        private fun JsonObject.text(key: String): String = (this[key] as JsonPrimitive).content
        private fun JsonObject.number(key: String): Long = (this[key] as JsonPrimitive).long
    }
}
